@IsTest private class PopulatedMapProbe62 {
@IsTest static void observeSnapshot() { Map<String,Object> out=new Map<String,Object>(); try { Account a=new Account(Name='first'); Map<String,Object> m=a.getPopulatedFieldsAsMap(); a.Name='second'; a.Description='added'; out.put('mapName',m.get('Name')); out.put('recordName',a.Name); out.put('hasAdded',m.containsKey('Description')); out.put('freshAdded',a.getPopulatedFieldsAsMap().containsKey('Description')); } catch(Exception e) { out.put('exceptionType',e.getTypeName()); out.put('exceptionMessage',e.getMessage()); } System.assert(false,'MAP|snapshot|'+JSON.serialize(out)); }
@IsTest static void observePut() { Map<String,Object> out=new Map<String,Object>(); try { Account a=new Account(Name='first'); Map<String,Object> m=a.getPopulatedFieldsAsMap(); m.put('Name','second'); out.put('mapName',m.get('Name')); out.put('recordName',a.Name); } catch(Exception e) { out.put('exceptionType',e.getTypeName()); out.put('exceptionMessage',e.getMessage()); } System.assert(false,'MAP|put|'+JSON.serialize(out)); }
@IsTest static void observeRemove() { Map<String,Object> out=new Map<String,Object>(); try { Account a=new Account(Name='first'); Map<String,Object> m=a.getPopulatedFieldsAsMap(); m.remove('Name'); out.put('hasName',m.containsKey('Name')); out.put('recordName',a.Name); } catch(Exception e) { out.put('exceptionType',e.getTypeName()); out.put('exceptionMessage',e.getMessage()); } System.assert(false,'MAP|remove|'+JSON.serialize(out)); }
@IsTest static void observeClear() { Map<String,Object> out=new Map<String,Object>(); try { Account a=new Account(Name='first'); Map<String,Object> m=a.getPopulatedFieldsAsMap(); m.clear(); out.put('size',m.size()); out.put('recordName',a.Name); } catch(Exception e) { out.put('exceptionType',e.getTypeName()); out.put('exceptionMessage',e.getMessage()); } System.assert(false,'MAP|clear|'+JSON.serialize(out)); }
@IsTest static void observePutall() { Map<String,Object> out=new Map<String,Object>(); try { Account a=new Account(Name='first'); Map<String,Object> m=a.getPopulatedFieldsAsMap(); m.putAll(new Map<String,Object>{'Name'=>'second'}); out.put('mapName',m.get('Name')); out.put('recordName',a.Name); } catch(Exception e) { out.put('exceptionType',e.getTypeName()); out.put('exceptionMessage',e.getMessage()); } System.assert(false,'MAP|putAll|'+JSON.serialize(out)); }
@IsTest static void observeCopy() { Map<String,Object> out=new Map<String,Object>(); try { Account a=new Account(Name='first'); Map<String,Object> m=new Map<String,Object>(a.getPopulatedFieldsAsMap()); m.put('Name','second'); m.remove('Name'); out.put('size',m.size()); out.put('recordName',a.Name); } catch(Exception e) { out.put('exceptionType',e.getTypeName()); out.put('exceptionMessage',e.getMessage()); } System.assert(false,'MAP|copy|'+JSON.serialize(out)); }
@IsTest static void observeKeys() { Map<String,Object> out=new Map<String,Object>(); try { Account a=new Account(Name='first'); Map<String,Object> m=a.getPopulatedFieldsAsMap(); Set<String> keys=m.keySet(); keys.remove('Name'); out.put('hasName',m.containsKey('Name')); out.put('keyHasName',keys.contains('Name')); out.put('recordName',a.Name); } catch(Exception e) { out.put('exceptionType',e.getTypeName()); out.put('exceptionMessage',e.getMessage()); } System.assert(false,'MAP|keys|'+JSON.serialize(out)); }
@IsTest static void observeRelationship() { Map<String,Object> out=new Map<String,Object>(); try { Account a=new Account(Name='first'); Contact c=new Contact(LastName='sample',Account=a); Map<String,Object> m=c.getPopulatedFieldsAsMap(); a.Name='second'; out.put('mapName',((Account)m.get('Account')).Name); out.put('recordName',c.Account.Name); } catch(Exception e) { out.put('exceptionType',e.getTypeName()); out.put('exceptionMessage',e.getMessage()); } System.assert(false,'MAP|relationship|'+JSON.serialize(out)); }
@IsTest static void observeClone() { Map<String,Object> out=new Map<String,Object>(); try { Account a=new Account(Name='first'); Map<String,Object> m=a.getPopulatedFieldsAsMap().clone(); m.put('Name','second'); out.put('mapName',m.get('Name')); out.put('recordName',a.Name); } catch(Exception e) { out.put('exceptionType',e.getTypeName()); out.put('exceptionMessage',e.getMessage()); } System.assert(false,'MAP|clone|'+JSON.serialize(out)); }
}

